import sys
from collections import Counter

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        k = int(next(iterator))
        n = int(next(iterator))
    except StopIteration:
        return

    strings = []
    for _ in range(k):
        try:
            s = next(iterator)
            strings.append(s)
        except StopIteration:
            break

    if len(strings) != k:
        print("-1")
        return

    def can_transform(target, source):
        diff_indices = []
        for i in range(n):
            if target[i] != source[i]:
                diff_indices.append(i)

        if len(diff_indices) == 0:
            return True

        if len(diff_indices) != 2:
            return False

        i, j = diff_indices
        return target[i] == source[j] and target[j] == source[i]

    def is_valid_candidate(candidate, all_strings):
        for s in all_strings:
            if not can_transform(candidate, s):
                return False
        return True

    if k == 1:
        candidate = strings[0]
        if is_valid_candidate(candidate, strings):
            print(candidate)
            return
        else:
            print("-1")
            return

    candidates = set()

    for s in strings:
        counter = Counter(s)
        base_list = list(s)

        for i in range(n):
            for j in range(i + 1, n):
                if base_list[i] != base_list[j]:
                    temp = base_list[:]
                    temp[i], temp[j] = temp[j], temp[i]
                    cand = "".join(temp)
                    candidates.add(cand)

        for char_code in range(ord('a'), ord('z') + 1):
            char = chr(char_code)
            if counter[char] > 0:
                idx = -1
                for p in range(n):
                    if base_list[p] == char:
                        idx = p
                        break

                if idx != -1:
                    for j in range(n):
                        if j != idx:
                            temp = base_list[:]
                            temp[idx], temp[j] = temp[j], temp[idx]
                            cand = "".join(temp)
                            candidates.add(cand)

        if n >= 2:
            for i in range(n):
                for j in range(i + 1, n):
                    temp = base_list[:]
                    temp[i], temp[j] == temp[j], temp[i]
                    cand = "".join(temp)

                    if is_valid_candidate(cand, strings):
                        print(cand)
                        return

    for cand in candidates:
        if is_valid_candidate(cand, strings):
            print(cand)
            return

    print("-1")

if __name__ == "__main__":
    solve()
